import {GUIDE_TOPICS} from './project-guide-topics.js';
/** Указатель пособия: короткие выжимки и следы сверки, без загрузки модели.
 * Текст новых статей хранится здесь один раз; прежние пояснения — в ui-text.
 * reviewedVersion=null означает перенос старой справки, а не новую полную сверку. */
export const GUIDE_ARTICLES=[
 {id:'intro',title:'О проекте и цели модели',summary:'Что исследует Big Evolution, чем наследование отличается от личного обучения и почему наблюдаемое поведение ещё не объясняет его причину.',reviewedVersion:'0.54.2',sources:[
  {file:'evolution.js',symbols:['addAgent','feeling'],purpose:'Создание жителя и связь физического состояния с субъективной оценкой.'},
  {file:'cognition.js',symbols:['createBrain'],purpose:'Пустое личное состояние и память нового организма.'},
  {file:'neural-brain.js',symbols:['createNeuralBrain'],purpose:'Наследуемая основа сети и отдельные личные поправки.'},
  {file:'temporal-world.js',symbols:['localTemporalObservation','complete'],purpose:'Доступное наблюдение и завершение действий, включая рождение.'},
  {file:'temporal-inputs.js',symbols:['prepareSetInput'],purpose:'Подготовка входов мозга из локальных сведений.'},
  {file:'set-brain-engine.js',symbols:['learnSetBrain'],purpose:'Обучение личных поправок без переписывания генома.'},
  {file:'brain-controller.js',symbols:['controllerFeeling'],purpose:'Субъективные ощущения с учётом знака чувствительностей.'},
 ],related:['world','brain','memory','genome','research','limits']},
 {id:'time',title:'Как идут время и события?',summary:'Т, подшаги, прогресс действий и порядок обновления мира. Когда происходит завершение, гибель и первое решение ребёнка.'},
 {id:'world',title:'Как запустить и наблюдать?',summary:'Запуск, пауза и подшаг; скорость наблюдения, выбор жителя и применение стартовых условий.'},
 {id:'saves',title:'Как сохранить мир?',summary:'Полное сохранение позволяет продолжить мир вместе с памятью и обучением. Геном, план и отчёт служат другим целям.'},
 {id:'actions',title:'Какие есть действия?',summary:'Перемещение, работа с пищей, ожидание и рождение. Действия занимают время; возможность действия зависит от состояния тела и среды.'},
 {id:'brain',title:'Как житель принимает решения?',summary:'Мозг оценивает допустимые варианты, выбирает действие и обучается на субъективных последствиях. Вычисления расходуют энергию.'},
 {id:'memory',title:'Что он помнит и чему учится?',summary:'Краткая и долгая память ограничены и могут забывать наблюдения. Личный опыт начинается заново у каждого новорождённого.'},
 {id:'selection',title:'Как рождаются потомки?',summary:'Условия начала и завершения родов, расход ресурсов родителя и самостоятельная жизнь ребёнка.'},
 {id:'genome',title:'Что наследуется?',summary:'Наследуемая структура мозга, исходные веса и свойства организма. Личная память и выученные поправки потомку не передаются.'},
 {id:'geography',title:'Что видно на карте?',summary:'Обзор жителя, личные q/r и мировой x/y, поворот взгляда, вода и границы. Пример объясняет, куда ведёт команда «вперёд».'},
 {id:'food',title:'Откуда берётся пища?',summary:'Источники, островки и восстановление пищи. Сбор, запас и усвоение связаны с ресурсами тела.'},
 {id:'deposits',title:'Что за еда без источника?',summary:'Отложенная жителями пища и остатки после гибели: их можно использовать, но они сами не восстанавливаются как источник.'},
 {id:'environment',title:'Как меняются источники пищи?',summary:'Автоматическая перестройка числа, размеров, расположения и периодов пищевых групп; ограничения переноса и сохранение лежащей еды.'},
 {id:'research',title:'Как читать результаты?',summary:'Сравнение жизни, потомства и популяции; повторные миры, субъективные оценки и правила фонового обновления графиков.'},
 {id:'checks',title:'Что проверяют испытания?',summary:'Проверки механизмов и длительные наблюдения отвечают на разные вопросы. Успешная проверка не гарантирует появления определённой стратегии.'},
 {id:'limits',title:'Что упрощено в модели?',summary:'Границы текущей симуляции, отсутствующие механики, ограничения населения и различия форматов сохранения и результатов.'},
].map(article=>{const topic=GUIDE_TOPICS[article.id]??{};return Object.freeze({reviewedVersion:null,sources:[],related:[],keywords:[],checks:[],...article,...topic,sources:[...(article.sources??[]),...(topic.sources??[])]});});

export const GUIDE_INTRO_TEXT={
 'guide-intro-brief':'Big Evolution — браузерная лаборатория для наблюдения за жизнью, размножением и изменением поколений организмов. Жители действуют в общей среде, расходуют ресурсы, получают опыт и оставляют потомков. Можно исследовать, какие наследуемые свойства сохраняются и как личное обучение меняет поведение за одну жизнь.',
 'guide-intro-goal':'Проект развивается в сторону исследования социального поведения, стаи и вожака.',
 'guide-intro-example':'Например, можно сравнить варианты с личным обучением и без него. Продолжительность жизни, численность населения и число детей описывают разные стороны результата. Если обучающиеся живут меньше, одного графика недостаточно, чтобы объяснить причину: различаться могут предпочтения, затраты на мышление, состав популяции и история отбора. Для проверки объяснения нужны контролируемые условия и повторные миры.',
 'guide-intro-world':'Мир исполняет действия и определяет их физические последствия. Мозг получает сведения о собственном теле, видимой окрестности и личном опыте; ему не передаётся вся карта наблюдателя. Возможность увидеть клетку и наличие старого воспоминания о ней — разные источники сведений.',
 'guide-intro-inheritance':'Геном задаёт наследуемую основу, в том числе структуру и исходные веса мозга. Ребёнок получает геном одного родителя с возможными мутациями. Его личная память пуста, а выученные родителем поправки весов не копируются. За жизнь обучается личное состояние мозга; наследуемый геном от этого не переписывается.',
 'guide-intro-preferences':'Субъективная оценка последствий зависит от наследуемых чувствительностей, в том числе к энергии, здоровью и наполненности желудка. Знак чувствительности может быть отрицательным. Поэтому приятное для жителя действие не обязательно продлевает его жизнь или увеличивает число потомков. Личное обучение, наследование и отбор следует различать.',
 'guide-intro-reading':'Начни с запуска мира или выбери тему слева. Поле «Найти в пособии» ищет по названиям, выжимкам, терминам, файлам и функциям. Стрелка раскрывает ветку, ссылка открывает статью. Наведение или фокус с клавиатуры показывают выжимку. Точные правила и блок «Где это в коде» раскрываются внутри статьи. Раздел «Полнота описания» показывает учёт исходников; ссылка на файл ещё не означает, что он полностью описан.',
};

export function guideArticleFromHash(hash){return GUIDE_ARTICLES.find(article=>hash===`#wiki-panel-${article.id}`)?.id??null;}
